OUT.write_text(json.dumps(result,indent=2)+'\n');print('written',OUT,flush=True)
for row in summary:
 if row['mode']=='mesh' and row['cap']==1_000_000:print(row,flush=True)
print('RSS',result['rss_summary'],flush=True)

